import{_ as a,o as i,c as t,ae as o}from"./chunks/framework.DPZ3sAUK.js";const p=JSON.parse('{"title":"neuron-js: AI-friendly TypeScript rules engine","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),r={name:"overview.md"};function n(s,e,l,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="neuron-js-ai-friendly-typescript-rules-engine" tabindex="-1">neuron-js: AI-friendly TypeScript rules engine <a class="header-anchor" href="#neuron-js-ai-friendly-typescript-rules-engine" aria-label="Permalink to &quot;neuron-js: AI-friendly TypeScript rules engine&quot;">​</a></h1><p><code>neuron-js</code> is a lightweight TypeScript rules engine for serializable JSON business rules and deterministic workflow decisions.</p><p>It lets teams define logic as structured data, execute that logic through a developer-owned registry, and run the same deterministic rules in Node.js or the browser.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Hardcoded business logic is fast at first, but it becomes rigid when product, compliance, pricing, routing, eligibility, or workflow rules change often.</p><p>Heavy workflow engines solve configurability, but they can add operational weight, proprietary formats, and integration overhead.</p><h2 id="the-solution" tabindex="-1">The solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The solution&quot;">​</a></h2><p><code>neuron-js</code> keeps business logic as JSON and executes it through a TypeScript registry.</p><ul><li><strong>Neuron</strong> defines what is allowed: parameters, conditions, actions, and rules.</li><li><strong>Synapse</strong> executes a serializable script against an execution context.</li><li><strong>ExecutionContext</strong> carries shared state and messages through the run.</li><li><strong>Lifecycle hooks</strong> expose script, rule, action, and error events for observability.</li></ul><p>This gives applications configurable logic without giving up deterministic execution or developer-owned boundaries.</p><h2 id="use-neuron-js-when" tabindex="-1">Use neuron-js when <a class="header-anchor" href="#use-neuron-js-when" aria-label="Permalink to &quot;Use neuron-js when&quot;">​</a></h2><ul><li>Rules must be stored in a database or versioned in Git.</li><li>Product teams need configurable logic without redeploying code.</li><li>AI-generated rules need validation and approved execution boundaries before runtime.</li><li>Frontend and backend code need to share deterministic decisions.</li><li>Workflow automation needs a predictable decision node instead of probabilistic LLM branching.</li><li>A full BPMN/workflow platform is too heavy for the problem.</li></ul><h2 id="do-not-use-neuron-js-when" tabindex="-1">Do not use neuron-js when <a class="header-anchor" href="#do-not-use-neuron-js-when" aria-label="Permalink to &quot;Do not use neuron-js when&quot;">​</a></h2><ul><li>A simple hardcoded condition is clearer and rarely changes.</li><li>Arbitrary user code execution is required.</li><li>You need a full BPMN/process orchestration platform.</li><li>Non-technical users need unrestricted rule authoring without validation, tests, review, and rollback.</li></ul><h2 id="core-architecture" tabindex="-1">Core architecture <a class="header-anchor" href="#core-architecture" aria-label="Permalink to &quot;Core architecture&quot;">​</a></h2><h3 id="neuron-registry" tabindex="-1">Neuron: registry <a class="header-anchor" href="#neuron-registry" aria-label="Permalink to &quot;Neuron: registry&quot;">​</a></h3><p>The <code>Neuron</code> registry owns the vocabulary of executable elements. By default, it registers built-in parameters, conditions, actions, and rules. Applications can register custom types to expose only approved capabilities.</p><h3 id="synapse-execution-engine" tabindex="-1">Synapse: execution engine <a class="header-anchor" href="#synapse-execution-engine" aria-label="Permalink to &quot;Synapse: execution engine&quot;">​</a></h3><p><code>Synapse</code> receives a <code>Neuron</code>, a serializable script, and an execution context. It evaluates rules, executes actions, and returns an execution result.</p><h3 id="script" tabindex="-1">Script <a class="header-anchor" href="#script" aria-label="Permalink to &quot;Script&quot;">​</a></h3><p>A script is a serializable collection of rules. It can be stored, transmitted, reviewed, and versioned as JSON.</p><h3 id="rule" tabindex="-1">Rule <a class="header-anchor" href="#rule" aria-label="Permalink to &quot;Rule&quot;">​</a></h3><p>A rule combines conditions and actions. Conditions decide whether the rule should run. Actions perform the approved operation.</p><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>The execution context stores messages and shared state for the run. Actions can return updated context for later rules.</p><h3 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h3><p>Lifecycle hooks let applications monitor execution without embedding observability directly into rule definitions.</p><h2 id="release-classification" tabindex="-1">Release classification <a class="header-anchor" href="#release-classification" aria-label="Permalink to &quot;Release classification&quot;">​</a></h2><p>The <code>0.4.0</code> release is a minor capability release, not a major breaking change.</p><p>It expands the documented public API, adds extension base classes, makes missing <code>options</code> objects safe at runtime, and cleans package output. Existing JSON script behavior remains compatible; the release gives consumers more stable imports and clearer plugin ergonomics.</p><h2 id="current-and-planned-adoption-assets" tabindex="-1">Current and planned adoption assets <a class="header-anchor" href="#current-and-planned-adoption-assets" aria-label="Permalink to &quot;Current and planned adoption assets&quot;">​</a></h2><p>Available now:</p><ul><li>npm package: <code>@sebasoft/neuron-js</code></li><li>GitHub repository: <a href="https://github.com/SebaSOFT/neuron-js" target="_blank" rel="noreferrer">https://github.com/SebaSOFT/neuron-js</a></li><li>Documentation site: <a href="https://sebasoft.github.io/neuron-js/" target="_blank" rel="noreferrer">https://sebasoft.github.io/neuron-js/</a></li><li>Core concepts and use-case documentation in this site</li></ul><p>Planned next:</p><ul><li>Runnable examples: <code>NJS-GROWTH-02</code></li><li>JSON Schemas, validation, and explain output: <code>NJS-GROWTH-03</code></li><li><code>llms.txt</code> and AI-assistant documentation: <code>NJS-GROWTH-04</code></li><li>Comparison and migration pages: <code>NJS-GROWTH-05</code></li></ul><h2 id="key-features" tabindex="-1">Key features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key features&quot;">​</a></h2><ul><li><strong>JSON Serializable</strong>: Logic is data that can be stored, transmitted, and audited.</li><li><strong>Shared Context</strong>: State and messages pass through the execution chain.</li><li><strong>Logical Grouping</strong>: AND/OR condition logic is supported by the rule model.</li><li><strong>Lifecycle Hooks</strong>: Observe execution at script, rule, action, and error boundaries.</li><li><strong>Type Safe</strong>: Built with TypeScript for a robust developer experience.</li></ul>',37)])])}const b=a(r,[["render",n]]);export{p as __pageData,b as default};
